-- prototype_seed_theme_weeks_v2.sql
-- ZASTĘPUJE prototype_seed_theme_weeks.sql (v1 miał realny błąd: cały temat
-- np. "Wirusologia" - 12 wykładów - stłoczony w 1 tydzień; zgłoszone przez
-- usera po obejrzeniu prototypu na żywo, 2026-07-27).
--
-- Teraz: dowiązanie NA POZIOMIE KATEGORII (nie całego tematu, patrz
-- assignStudyUnitOrdinalsByTheme w build_questions.mjs) - mikrobiologia 5
-- kategorii/tydzień (100 kategorii -> 20 tygodni), fizjopato 6/tydzień (126
-- kategorii -> 21 tygodni). Tempo WCIĄŻ przybliżone (nie znamy realnego
-- sylabusu) ale dużo bliższe realiom niż "cały temat na raz".
--
-- BEZPIECZNE odpalić nawet jeśli v1 już był uruchomiony - najpierw czyści
-- STARE wiersze tych dwóch przedmiotów (DELETE), dopiero potem wstawia nowe.
-- Prostsze i pewniejsze niż ON CONFLICT DO UPDATE na indeksie z wyrażeniem
-- (coalesce(group_number,0)) z supabase_schema_study_plan_groups.sql - ten
-- indeks nie mapuje się bezpośrednio na klauzulę ON CONFLICT (col, col, col).
delete from public.study_units where subject_key in ('mikrobiologia', 'fizjopato');

on conflict (key) do nothing;

on conflict do nothing;
